macro_rules! deps {
    () => {
        Name!();
        Object!();
        Import!();
        Table!();
        U16!();
        U32!();
    };
}

macro_rules! ImageVxdHeader {
    () => {
        deps!();
        # [doc = " Windows VXD header"] # [derive (Debug , Clone , Copy)] # [repr (C)] pub struct ImageVxdHeader { # [doc = " Magic number"] pub e32_magic : U16 < LE > , # [doc = " The byte ordering for the VXD"] pub e32_border : u8 , # [doc = " The word ordering for the VXD"] pub e32_worder : u8 , # [doc = " The EXE format level for now = 0"] pub e32_level : U32 < LE > , # [doc = " The CPU type"] pub e32_cpu : U16 < LE > , # [doc = " The OS type"] pub e32_os : U16 < LE > , # [doc = " Module version"] pub e32_ver : U32 < LE > , # [doc = " Module flags"] pub e32_mflags : U32 < LE > , # [doc = " Module # pages"] pub e32_mpages : U32 < LE > , # [doc = " Object # for instruction pointer"] pub e32_startobj : U32 < LE > , # [doc = " Extended instruction pointer"] pub e32_eip : U32 < LE > , # [doc = " Object # for stack pointer"] pub e32_stackobj : U32 < LE > , # [doc = " Extended stack pointer"] pub e32_esp : U32 < LE > , # [doc = " VXD page size"] pub e32_pagesize : U32 < LE > , # [doc = " Last page size in VXD"] pub e32_lastpagesize : U32 < LE > , # [doc = " Fixup section size"] pub e32_fixupsize : U32 < LE > , # [doc = " Fixup section checksum"] pub e32_fixupsum : U32 < LE > , # [doc = " Loader section size"] pub e32_ldrsize : U32 < LE > , # [doc = " Loader section checksum"] pub e32_ldrsum : U32 < LE > , # [doc = " Object table offset"] pub e32_objtab : U32 < LE > , # [doc = " Number of objects in module"] pub e32_objcnt : U32 < LE > , # [doc = " Object page map offset"] pub e32_objmap : U32 < LE > , # [doc = " Object iterated data map offset"] pub e32_itermap : U32 < LE > , # [doc = " Offset of Resource Table"] pub e32_rsrctab : U32 < LE > , # [doc = " Number of resource entries"] pub e32_rsrccnt : U32 < LE > , # [doc = " Offset of resident name table"] pub e32_restab : U32 < LE > , # [doc = " Offset of Entry Table"] pub e32_enttab : U32 < LE > , # [doc = " Offset of Module Directive Table"] pub e32_dirtab : U32 < LE > , # [doc = " Number of module directives"] pub e32_dircnt : U32 < LE > , # [doc = " Offset of Fixup Page Table"] pub e32_fpagetab : U32 < LE > , # [doc = " Offset of Fixup Record Table"] pub e32_frectab : U32 < LE > , # [doc = " Offset of Import Module Name Table"] pub e32_impmod : U32 < LE > , # [doc = " Number of entries in Import Module Name Table"] pub e32_impmodcnt : U32 < LE > , # [doc = " Offset of Import Procedure Name Table"] pub e32_impproc : U32 < LE > , # [doc = " Offset of Per-Page Checksum Table"] pub e32_pagesum : U32 < LE > , # [doc = " Offset of Enumerated Data Pages"] pub e32_datapage : U32 < LE > , # [doc = " Number of preload pages"] pub e32_preload : U32 < LE > , # [doc = " Offset of Non-resident Names Table"] pub e32_nrestab : U32 < LE > , # [doc = " Size of Non-resident Name Table"] pub e32_cbnrestab : U32 < LE > , # [doc = " Non-resident Name Table Checksum"] pub e32_nressum : U32 < LE > , # [doc = " Object # for automatic data object"] pub e32_autodata : U32 < LE > , # [doc = " Offset of the debugging information"] pub e32_debuginfo : U32 < LE > , # [doc = " The length of the debugging info. in bytes"] pub e32_debuglen : U32 < LE > , # [doc = " Number of instance pages in preload section of VXD file"] pub e32_instpreload : U32 < LE > , # [doc = " Number of instance pages in demand load section of VXD file"] pub e32_instdemand : U32 < LE > , # [doc = " Size of heap - for 16-bit apps"] pub e32_heapsize : U32 < LE > , # [doc = " Reserved words"] pub e32_res3 : [u8 ; 12] , pub e32_winresoff : U32 < LE > , pub e32_winreslen : U32 < LE > , # [doc = " Device ID for VxD"] pub e32_devid : U16 < LE > , # [doc = " DDK version for VxD"] pub e32_ddkver : U16 < LE > , }
    };
}

ImageVxdHeader!();